// DefaultLanguages returns the built-in native languages configured for the site.
func DefaultLanguages() []LanguageItem {
	return []LanguageItem{
		{Code: "zh-CN", Name: "简体中文", NativeName: "简体中文", Badge: "中文", Direction: "ltr", Enabled: true, SortOrder: 1},
		{Code: "en-US", Name: "English", NativeName: "English", Badge: "EN", Direction: "ltr", Enabled: true, SortOrder: 2},
		{Code: "zh-TW", Name: "繁體中文", NativeName: "繁體中文", Badge: "繁中", Direction: "ltr", Enabled: true, SortOrder: 3},
		{Code: "es-ES", Name: "Español", NativeName: "Español", Badge: "ES", Direction: "ltr", Enabled: true, SortOrder: 4},
		{Code: "fr-FR", Name: "Français", NativeName: "Français", Badge: "FR", Direction: "ltr", Enabled: true, SortOrder: 5},
		{Code: "de-DE", Name: "Deutsch", NativeName: "Deutsch", Badge: "DE", Direction: "ltr", Enabled: true, SortOrder: 6},
		{Code: "ja-JP", Name: "日本語", NativeName: "日本語", Badge: "日本語", Direction: "ltr", Enabled: true, SortOrder: 7},
		{Code: "ko-KR", Name: "한국어", NativeName: "한국어", Badge: "한국어", Direction: "ltr", Enabled: true, SortOrder: 8},
	}
}

// DefaultSettings returns the out-of-the-box configuration for supdance-i18n.
func DefaultSettings() Settings {
	return Settings{
		DefaultLocale:         LocaleZhCN,
		FallbackLocale:        LocaleZhCN,
		AutoDetectBrowser:     true,
		SwitcherStyle:         SwitcherStyleIconCode,
		ShowInWorkspaceTopBar: true,
		ShowInAuthPage:        true,
		ShowInCanvasTopBar:    true,
		ShowInAdminTopBar:     true,
		TranslateAdminPages:   false,
		Languages:             DefaultLanguages(),
		Revision:              "builtin-v1",
	}
}

func entry(key, ns, zhCN, enUS, zhTW, jaJP, koKR, esES, frFR, deDE, desc string) Entry {
	return Entry{
		Key:         key,
		Namespace:   ns,
		SourceText:  zhCN,
		Description: desc,
		Origin:      EntryOriginBuiltin,
		Translations: map[string]string{
			LocaleZhCN: zhCN,
			LocaleEnUS: enUS,
			LocaleZhTW: zhTW,
			LocaleJaJP: jaJP,
			LocaleKoKR: koKR,
			LocaleEsES: esES,
			LocaleFrFR: frFR,
			LocaleDeDE: deDE,
		},
	}
}

